def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)
    outcome = result.get("outcome")
    limit = result.get("credit_limit", 0) or 0

    # Network referral rule: self_employed with requested_limit above 4000
    # goes to manual review instead of being issued (a decline stays a decline).
    if (app.get("employment") == "self_employed"
            and (app.get("requested_limit") or 0) > 4000
            and outcome == "approved"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review (v2) / refer (v1)
    return {"action": "queue_review", "limit": 0}
